AssistantMessageToolRequest(name='create', tool_call_id='toolu_015ETbcfgePj3bHnS3ALRDWW', arguments={'path': '/workspace/sandbox/skills/building-accessible-ui/checkbox-group--framework-vanilla-js--style-dark/claude-opus-4.7__s3/script.js', 'file_text': '(function () {
  'use strict';

  const ANSWERS = {
    q1: { correct: ['java', 'rust'], label: 'Statically typed languages' },
    q2: { correct: ['c', 'cpp'], label: 'Created at Bell Labs' },
    q3: { correct: ['kotlin', 'scala', 'clojure'], label: 'Run on the JVM' }
  };

  const form = document.getElementById('quiz-form');
  const result = document.getElementById('result');

  function getSelected(name) {
    return Array.from(
      form.querySelectorAll('input[name="' + name + '"]:checked')
    ).map(el => el.value);
  }

  function arraysEqualAsSets(a, b) {
    if (a.length !== b.length) return false;
    const sa = new Set(a);
    return b.every(v => sa.has(v));
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();

    let score = 0;
    const items = [];
    Object.keys(ANSWERS).forEach(function (q) {
      const picked = getSelected(q);
      const isCorrect = arraysEqualAsSets(picked, ANSWERS[q].correct);
      if (isCorrect) score++;
      items.push(
        '<li class="' + (isCorrect ? 'correct' : 'incorrect') + '">' +
        ANSWERS[q].label + ': ' +
        (isCorrect ? 'Correct' : 'Incorrect — answer: ' + ANSWERS[q].correct.join(', ')) +
        '</li>'
      );
    });

    result.innerHTML =
      '<h2>Results</h2>' +
      '<p class="score">You scored ' + score + ' out of ' + Object.keys(ANSWERS).length + '.</p>' +
      '<ul>' + items.join('') + '</ul>';
  });
})();
